import test from 'node:test';import assert from 'node:assert/strict';
import {execute} from '../core/api.mjs';import {calculators} from '../core/definitions.mjs';
const p={initialPln:'0',monthlyPln:'100',years:1,annualReturnPercent:0,annualFixedFeePln:'0',annualFeePercent:0};
const c={...p,group:'I',futureTaxPercent:.85,thresholdIndexationPercent:0};
for(const d of calculators)test(`Przykład ${d.id}: ${d.name}`,()=>{const r=execute(d.tool,d.example);assert.equal(r.status,'ok',JSON.stringify(r));assert.equal(r.calculationVersion,'1.0.0');assert.doesNotThrow(()=>JSON.stringify(r));});
const metric=(r,label)=>Number(r.metrics.find(m=>m.label.includes(label)).value);
test('cel: 12 wpłat bez zwrotu i kosztów',()=>{const r=execute('solve_oki_goal',{...p,monthlyPln:'0',targetPln:'1200',mode:'contribution'});assert.equal(metric(r,'Miesięczna'),100);});
test('cel nieosiągalny i już osiągnięty',()=>{assert.equal(execute('solve_oki_goal',{...p,targetPln:'9999999999',mode:'time'}).status,'no_solution');assert.equal(metric(execute('solve_oki_goal',{...p,initialPln:'1000',targetPln:'500',mode:'time'}),'Lata'),0);});
test('przerwa 6 miesięcy bez zwrotu: połowa wpłat',()=>{const r=execute('simulate_flexible_plan',{...p,mode:'pause',pauseFromMonth:1,pauseMonths:6});assert.equal(metric(r,'Kapitał na końcu'),600);});
test('nieregularna lista zastępuje plan bazowy i sumuje miesiąc',()=>{const r=execute('simulate_flexible_plan',{...p,mode:'schedule',deposits:[{month:1,amountPln:'100'},{month:1,amountPln:'200'},{month:12,amountPln:'400'}]});assert.equal(metric(r,'Kapitał na końcu'),700);});
test('przerwa poza horyzontem i wpłata poza listą nie dają sukcesu',()=>{assert.equal(execute('simulate_flexible_plan',{...p,mode:'pause',pauseFromMonth:12,pauseMonths:2}).status,'invalid_input');assert.equal(execute('simulate_flexible_plan',{...p,mode:'schedule',deposits:[{month:13,amountPln:'100'}]}).status,'invalid_input');});
test('rosnące wpłaty: po pierwszym roku nowa kwota',()=>{const r=execute('simulate_flexible_plan',{...p,years:2,mode:'growth',annualContributionGrowthPercent:10});assert.equal(metric(r,'Kapitał na końcu'),2520);});
test('wypłata 12000 przez 12 miesięcy, bez wzrostu: 1000',()=>{const r=execute('simulate_oki_withdrawals',{...p,initialPln:'12000',monthlyPln:'0',mode:'solve'});assert.equal(metric(r,'Miesięczna'),1000);assert.equal(metric(r,'Pozostały'),0);});
test('brak kapitału nie staje się pełną wypłatą',()=>{const r=execute('simulate_flexible_plan',{...p,mode:'expense',expenseMonth:1,expensePln:'1000'});assert.equal(r.status,'insufficient_funds');assert.equal(metric(r,'Wypłacono'),100);});
test('odwrócenie zwrotów bez wpłat i wypłat zachowuje wynik',()=>{const r=execute('compare_return_sequences',{...p,initialPln:'1000',monthlyPln:'0',years:3,annualReturnsPercent:[-20,5,30],monthlyWithdrawalPln:'0'});assert.equal(metric(r,'kolejność podana'),metric(r,'kolejność odwrócona'));});
test('podział 0 i 100 procent odpowiada niepodzielonym wariantom',()=>{for(const share of [0,100]){const r=execute('compare_oki_allocation',{...c,okiSharePercent:share}),base=execute('compare_oki_scenarios',c);assert.equal(metric(r,'podzielonego'),Number(share===0?base.ordinary.netBalancePln:base.oki.balancePln));}});
test('dwie osoby mają osobne zwolnienia',()=>{const r=execute('simulate_family_plans',{...c,initialPln:'100000',monthlyPln:'0',secondInitialPln:'100000',secondMonthlyPln:'0',secondGroup:'I'});assert.equal(metric(r,'Suma planów'),200000);assert.equal(metric(r,'podatków'),0);});
test('zmiana wyłącznie stawki przyszłej nie zmienia roku 2027',()=>{const r=execute('compare_future_tax_rates',{...c,initialPln:'150000',alternativeTaxPercent:2});assert.equal(r.metrics[0].value,r.metrics[1].value);});
test('historia kompletna: stałe 150 tys. I daje 425 zł',()=>{const spec=calculators.find(c=>c.id==='S18'),r=execute(spec.tool,spec.example);assert.equal(metric(r,'Kwota przed'),425);const rows=spec.example.rows;assert.equal(execute(spec.tool,{...spec.example,rows:rows.slice(1)}).status,'needs_data');assert.equal(execute(spec.tool,{...spec.example,rows:rows.map((r,i)=>i===0?{...r,depositPln:'1',withdrawalPln:'1'}:r)}).status,'unsupported_case');});
test('przepływ w końcu roku nie zeruje całej średniej',()=>{const r=execute('simulate_oki_cashflow_date',{initialPln:'150000',annualReturnPercent:0,group:'I',flowDate:'2027-12-31',flowPln:'150000',direction:'withdrawal'});assert.ok(metric(r,'po zmianie')>420);});
test('kwalifikowana wypłata: IKE bez PIT, IKZE 10%, korzyść osobno',()=>{const spec=calculators.find(c=>c.id==='S17');const r=execute(spec.tool,{...spec.example,annualReturnPercent:0,annualFixedFeePln:'0',annualFeePercent:0});assert.equal(metric(r,'IKE przy'),60000);assert.equal(metric(r,'IKZE po'),54000);assert.equal(metric(r,'osobna gotówka'),7200);assert.equal(execute(spec.tool,{...spec.example,currentAge:18}).status,'unsupported_case');assert.equal(execute(spec.tool,{...spec.example,assumedIkzeAnnualLimitPln:'1'}).status,'unsupported_case');});
